fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // We expect 1 <= k < list.len(), so that we're not removing the last element
    assert!(k >= 1, "k must be at least 1 (1-based indexing)");
    assert!(k < list.len(), "k must be strictly less than the length of the list");

    // Allocate a new vector of size n-1
    let mut new_list = Vec::with_capacity(list.len() - 1);

    // Copy the prefix [0..k-1) (in 0-based indexing, that's all elements before the removed one)
    new_list.extend_from_slice(&list[..k - 1]);

    // Copy the suffix [k..len)
    new_list.extend_from_slice(&list[k..]);

    new_list
}

fn main() {
    let v = vec![10, 20, 30, 40, 50];
    // Remove the 2nd element (1-based), which is 20
    let result = remove_kth_element(&v, 2);
    assert_eq!(result, vec![10, 30, 40, 50]);

    // Remove the 4th element (1-based), which is 40
    let result = remove_kth_element(&v, 4);
    assert_eq!(result, vec![10, 20, 30, 50]);

    println!("All tests passed!");
}